<?php $posts=db()->query("SELECT p.*,u.name FROM posts p JOIN users u ON u.id=p.user_id ORDER BY p.id DESC");?>
<section class="page-title"><span class="eyebrow">COMMUNITY</span><h1>Talk skincare, share routines.</h1><p>Post tips, experiences, and routine ideas.</p></section>
<?php if(logged_in()):?><div class="panel"><h2>Create a post</h2><form method="post" action="actions.php"><input type="hidden" name="action" value="post"><input name="title" required placeholder="Post title"><textarea name="body" required placeholder="Share your experience…"></textarea><button class="btn primary">Publish</button></form></div><?php endif;?>
<div class="post-list"><?php while($p=$posts->fetch_assoc()):?><article class="post"><div class="post-meta"><span class="avatar small"><?=e(strtoupper(substr($p['name'],0,1)))?></span><b><?=e($p['name'])?></b><small><?=date('d M Y',strtotime($p['created_at']))?></small></div><h2><?=e($p['title'])?></h2><p><?=nl2br(e($p['body']))?></p></article><?php endwhile;?></div>